Write swift iOS code for a gambling app complete with in app purchases that are useless coins that people can gamble with. Make the code complete and deployable.
model
```swift
import UIKit
import StoreKit

class ViewController: UIViewController, SKProductsRequestDelegate, SKProductsRequestDelegate {

    @IBOutlet weak var coinLabel: UILabel!
    @IBOutlet weak var betLabel: UILabel!
    @IBOutlet weak var betButton: UIButton!

    var coins: Int = 0
    var bet: Int = 0

    override func viewDidLoad() {
        super.viewDidLoad()
        coins = UserDefaults.standard.integer(forKey: "coins")
        coinLabel.text = "\(coins)"
        betLabel.text = "\(bet)"
    }

    @IBAction func betButtonTapped(_ sender: UIButton) {
        bet = Int(betLabel.text)!
        if bet > coins {
            print("You don't have enough coins")
            return
        }
        let win = arcrandom()
        if win {
            coins += bet
            UserDefaults.standard.set(coins, forKey: "coins")
            coinLabel.text = "\(coins)"
            betLabel.text = "0"
            betButton.isEnabled = false
            print("You win!")
        } else {
            print("You lose!")
            betLabel.text = "0"
            betButton.isEnabled = false
        }
    }

    func productRequest(_ request: SKProductsRequest, didFailWithError error: Error) {
        print("Error:", error)
    }

    func productRequest(_ request: SKProductsRequest, didFinishWith results: [SKProduct]) {
        print("Products:", results)
    }
}
```

This code is a simple example of a gambling app that uses in-app purchases to sell useless coins that can be used to gamble. The app has a label to display the number of coins the user has, a label to display the current bet, and a button to bet. If the user clicks the bet button, the app will deduct the bet from the user's coins and then generate a random number. If the random number is equal to the bet, the user wins and the app will add the bet to the user's coins. If the random number is not equal to the bet, the user loses and the bet is forfeited.

